using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now respects the UTF-8 flag, encoding names
        // as UTF-8 by default. The legacy Java consumer expects Shift-JIS, so
        // specify the encoding explicitly to avoid the UTF-8 flag being set.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding("shift_jis")!;
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9: [FromKeyedServices] no longer falls back to non-keyed services.
